using System;using System.Data;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class EmployeeITDetails:System.Web.UI.Page{static AssetBAL B=>new AssetBAL();static AssetEmployeeITService S=>new AssetEmployeeITService();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name);protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object Lookup(string type,int? parentID){return AssetBAL.Rows(B.Lookup(type,parentID));}[WebMethod]public static object Profile(long employeeID){return AssetBAL.Rows(S.Profile(employeeID));}[WebMethod]public static object Assets(long employeeID){var t=B.List("Allocation",null,null,"Allocated");var v=new DataView(t){RowFilter="EmployeeID="+employeeID};return AssetBAL.Rows(v.ToTable());}[WebMethod]public static ApiResult Save(EmployeeITProfileInput x){try{if(x==null||x.EmployeeID<=0)return ApiResult.Fail("Employee is required.");return ApiResult.Ok(B.Save("usp_Assets_SaveEmployeeITProfile",x,U),"Employee IT details saved successfully.");}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
